<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ServiceProvider} from '@/services/service-provider';import type {User} from '@/types/user';const route=useRoute();const router=useRouter();const users=ref<User[]>([]);const loading=ref(false);const error=ref('');const q=ref(String(route.query.q||''));const page=computed(()=>Math.max(1,Number(route.query.page||1)));const limit=10;async function load(){loading.value=true;error.value='';try{users.value=await ServiceProvider.users.getAll({limit,skip:(page.value-1)*limit,q:q.value})}catch(e){error.value=(e as Error).message}finally{loading.value=false}}function search(){router.push({query:{q:q.value||undefined,page:1}})}function change(delta:number){router.push({query:{q:q.value||undefined,page:page.value+delta}})}watch(()=>route.fullPath,load,{immediate:true})</script>
<section><div class="page-heading"><div><p class="eyebrow">SECURE AREA</p><h1>Користувачі</h1></div><span class="badge">Page {{page}}</span></div><div class="toolbar"><input v-model="q" placeholder="Пошук користувача..." @keyup.enter="search"/><button class="button" @click="search">Знайти</button></div><p v-if="loading" class="state">Завантаження...</p><p v-else-if="error" class="error state">{{error}}</p><div v-else class="user-grid"><RouterLink v-for="user in users" :key="user.id" class="user-card" :to="`/users/${user.id}`"><img :src="user.image" alt=""/><div><strong>{{user.firstName}} {{user.lastName}}</strong><small>{{user.email}}</small><small>@{{user.username}}</small></div></RouterLink></div><div class="pagination"><button :disabled="page===1" @click="change(-1)">← Назад</button><span>Сторінка {{page}}</span><button :disabled="users.length<limit" @click="change(1)">Далі →</button></div></section>
